// Validacion de entrada del canal de correo — Anexo H §H.3
// Verifica que la descripcion exista, no este vacia y tenga al menos 10 caracteres.
// Si la validacion falla, emite es_valido=false para que el nodo IF rutee al reenvio.
// Limite maximo: 5000 caracteres (contrato IncidenteCreate del backend).

const items = $input.all();
const result = [];

for (const item of items) {
  // C-55: el trigger IMAP (format simple) entrega textPlain/textHtml/text.
  const descripcion =
    item.json.descripcion || item.json.textPlain || item.json.textHtml || item.json.text || item.json.body || '';
  const descripcionTrim = String(descripcion).trim();

  const esValida = descripcionTrim.length >= 10 && descripcionTrim.length <= 5000;

  result.push({
    json: {
      ...item.json,
      // C-39: sella el instante de ingreso al INICIO del flujo del trigger
      // IMAP (recogida del poller), NO con la fecha del mensaje.
      ingresado_en: new Date().toISOString(),
      descripcion: descripcionTrim,
      es_valido: esValida,
      canal_raw: 'correo'
    }
  });
}

return result;

// C-56: prepara UN item por destinatario resuelto por el backend.
// Lee `destinatarios_revision` de la respuesta del alta; si viene vacio o
// ausente, usa el respaldo unico `$env.OPERATOR_EMAIL`. Emite un item por
// destinatario para que emailSend envie una copia a cada uno, sin exponer la
// lista completa en un To/Cc/Bcc compartido.
const respuesta = $input.first().json || {};
const numero = respuesta.numero_incidente || null;
const lista = Array.isArray(respuesta.destinatarios_revision)
  ? respuesta.destinatarios_revision.filter((d) => typeof d === 'string' && d.trim())
  : [];
const destinatarios = lista.length > 0 ? lista : [$env.OPERATOR_EMAIL].filter(Boolean);
return destinatarios.map((destinatario) => ({
  json: { destinatario, numero_incidente: numero }
}));

// C-52 (N8N-PHONE-004): el instante de ingreso de telefonia lo sella el
// BACKEND al recibir el callback de grabacion (design.md D4). n8n NO lo
// regenera: este nodo PROPAGA el `ingresado_en` del handoff y normaliza la
// descripcion pseudonimizada al campo `descripcion` del item corriente, de
// modo que la latencia end-to-end incluya descarga, STT, pseudonimizacion y
// handoff del backend.
//
// F1 (fix de llamada real): el webhook de n8n entrega el body HTTP NESTED bajo
// `body` (item shape {headers, params, query, body, ...}). Se lee el payload
// anidado y se aplana al item corriente (descripcion, ingresado_en, call_sid,
// caller_number, canal_raw) para que los nodos aguas abajo sigan operando.
const item = $input.item;
const body =
  item.json && typeof item.json.body === 'object' && item.json.body !== null
    ? item.json.body
    : {};
const ingresadoEn =
  body.ingresado_en === undefined ? null : body.ingresado_en;
return [
  {
    json: {
      ...item.json,
      descripcion:
        body.descripcion_pseudonimizada || item.json.descripcion || '',
      ingresado_en: ingresadoEn,
      call_sid: body.call_sid || item.json.call_sid || null,
      caller_number: body.caller_number || item.json.caller_number || null,
      canal_raw: 'telefonia'
    }
  }
];

// Normalizacion de entrada a estructura unificada — tesis §5.3
// Homogeniza la entrada de cualquiera de los tres canales:
//   correo, web, telefonia
// Produce: { id, timestamp, canal_origen, canal_origen_id, descripcion, prioridad, es_valido, confianza }
// canal_origen debe ser uno de: correo, web, telefonia
//
// canal_origen_id: id del catalogo canal_origen de la migracion 001:
//   correo electronico -> 1, formulario web -> 2, llamada telefonica -> 3.
//   Se envia en el body del POST para que el incidente no quede con canal NULL (B-08).
//
// confianza: el IF compartido 'Entrada valida' evalua confianza >= 0.70.
//   - telefonia: propaga la confianza del validador de IA (ya existe en el item).
//   - correo/web: sintetiza confianza desde es_valido:
//       es_valido = true  -> confianza = 1.0 (datos completos, pasa el umbral)
//       es_valido = false -> confianza = 0.0 (datos incompletos, rama false del IF)
// Esto garantiza que el IF compartido funcione para los tres canales.
//
// Nota de privacidad (C-04 Decision 2):
//   La descripcion se transmite en texto claro al backend.
//   La pseudonimizacion ocurre en el backend (IncidenteService.create_and_classify).
//   El transporte usa HTTPS.

const items = $input.all();
const result = [];

const CANALES_VALIDOS = new Set(['correo', 'web', 'telefonia']);
const CANAL_ORIGEN_ID = { correo: 1, web: 2, telefonia: 3 };

// C-53 (N8N-EMAIL-002): extrae la direccion efectiva del remitente admitiendo
// `from` string y `from.emailAddress.address` (objeto de Outlook). Un remitente
// que no resuelva a una direccion valida se descarta (senal observable).
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function normalizarRemitente(raw) {
  let candidato = null;
  if (typeof raw === 'string') {
    // C-55: el header IMAP `from` suele venir como "Nombre <addr>".
    // Se extrae la direccion entre <> antes de validar con EMAIL_RE.
    const entreCorchetes = raw.match(/<([^>]+)>/);
    candidato = entreCorchetes ? entreCorchetes[1] : raw;
  } else if (raw && typeof raw === 'object') {
    candidato =
      (raw.emailAddress && raw.emailAddress.address) ||
      raw.address ||
      null;
  }
  if (typeof candidato !== 'string') {
    return { remitente: null, invalido: raw != null };
  }
  candidato = candidato.trim();
  if (!candidato || !EMAIL_RE.test(candidato)) {
    return { remitente: null, invalido: true };
  }
  return { remitente: candidato, invalido: false };
}

for (const item of items) {
  // Determinar canal segun lo marcado por el nodo previo
  const canalRaw = item.json.canal_raw || 'correo';
  const canalOrigen = CANALES_VALIDOS.has(canalRaw) ? canalRaw : null;

  if (!canalOrigen) {
    // Canal invalido: derivar a revision humana
    result.push({
      json: {
        ...item.json,
        canal_origen: canalRaw,
        canal_origen_id: null,
        es_valido: false,
        confianza: 0.0,
        error_normalizacion: 'canal_invalido'
      }
    });
    continue;
  }

  // Extraer descripcion segun canal
  // Webhook N8N: body del formulario web llega como objeto anidado en item.json.body
  const webBody = (canalOrigen === 'web' && typeof item.json.body === 'object' && item.json.body !== null) ? item.json.body : {};
  let descripcion = '';
  if (canalOrigen === 'correo') {
    // C-55: el trigger IMAP (format simple) entrega textPlain/textHtml/text.
    descripcion = item.json.descripcion || item.json.textPlain || item.json.textHtml || item.json.text || item.json.body || '';
  } else if (canalOrigen === 'telefonia') {
    descripcion = item.json.descripcion || item.json.output || item.json.text || '';
  } else if (canalOrigen === 'web') {
    // Webhook N8N: body del formulario llega como item.json.body (objeto anidado)
    // webBody se declara antes del if-chain; aqui solo se extrae descripcion
    descripcion = webBody.descripcion || item.json.descripcion || item.json.message || '';
  }

  // Sintetizar confianza para el IF compartido.
  // c-72: la telefonia ya no produce una clasificacion en n8n; se deriva de
  // es_valido (1.0 valido / 0.0 invalido), igual que correo y web. Un terminal
  // de revision (Derivar a revision humana) fija confianza 0.0 explicita.
  const esValido = item.json.es_valido !== undefined ? item.json.es_valido : true;
  const confianzaUpstream = item.json.confianza;
  const confianza =
    typeof confianzaUpstream === 'number'
      ? confianzaUpstream
      : (esValido ? 1.0 : 0.0);

  // C-33: metadatos de idempotencia, clasificacion precalculada y revision forzada.
  const revisionForzada = item.json.revision_forzada === true;
  const requiereRevision = item.json.requiere_revision_humana === true || revisionForzada;
  // C-52: la telefonía reutiliza el índice único de origen_message_id con el
  // CallSid del handoff para la idempotencia del alta.
  // C-55: el trigger IMAP no emite `id`; el Message-ID vive en el header
  // `metadata['message-id']` y, si falta, se usa el UID del mensaje.
  const messageIdHeader =
    (item.json.metadata && item.json.metadata['message-id']) || null;
  const uidFallback =
    (item.json.attributes && item.json.attributes.uid != null)
      ? String(item.json.attributes.uid)
      : null;
  // C-69 (OQ-A): el canal web SIEMPRE declara un origen_message_id no nulo.
  // Precedencia: id deterministico del llamador (webBody.origen_message_id,
  // o webBody.case_id -> 'corpus-<case_id>', o item.json.origen_message_id) y,
  // en su ausencia, un id unico por envio ('web-<execution.id>-<timestamp>').
  // La base ($execution.id) es unica por ejecucion: dos envios web legitimos
  // distintos NUNCA colisionan. Las ramas correo y telefonia NO cambian.
  const WEB_ORIGEN_PREFIX = 'web-';
  const webOrigenExplicito =
    (webBody && webBody.origen_message_id) ||
    (webBody && webBody.case_id ? 'corpus-' + webBody.case_id : null) ||
    item.json.origen_message_id ||
    null;
  const webOrigenGenerado = WEB_ORIGEN_PREFIX + $execution.id + '-' + Date.now();
  const origenMessageId =
    canalOrigen === 'correo'
      ? (messageIdHeader || uidFallback)
      : canalOrigen === 'telefonia'
        ? (item.json.call_sid || null)
        : (webOrigenExplicito || webOrigenGenerado);
  // C-53 (N8N-EMAIL-002): normaliza el remitente del canal correo. El `from`
  // de Outlook puede llegar como string o como objeto (`from.emailAddress.address`);
  // un remitente que no resuelva a una direccion valida se descarta con senal
  // observable y NO se propaga como destinatario invalido.
  const remitenteRaw = item.json.remitente || item.json.from || null;
  const remitenteNorm = normalizarRemitente(remitenteRaw);
  if (remitenteNorm.invalido && remitenteRaw != null) {
    console.warn(
      '[N8N][N8N-EMAIL-002] remitente_descartado',
      JSON.stringify({ evento: 'remitente_descartado', canal: canalOrigen })
    );
  }

  result.push({
    json: {
      id: item.json.id || $execution.id + '-' + Date.now(),
      timestamp: new Date().toISOString(),
      canal_origen: canalOrigen,
      canal_origen_id: CANAL_ORIGEN_ID[canalOrigen],
      ingresado_en: item.json.ingresado_en || null,  // C-39: instante de ingreso
      descripcion: String(descripcion).trim(),
      // C-40/C-53 (N8N-EMAIL-002): remitente original normalizado para la
      // confirmacion por correo. Viaja solo en el item normalizado (contexto N8N);
      // NO se agrega al POST ni a la auditoria.
      remitente: remitenteNorm.remitente,
      remitente_invalido: remitenteNorm.invalido,
      prioridad: (canalOrigen === 'web' ? (webBody.prioridad || item.json.prioridad) : item.json.prioridad) || 'media',
      es_valido: esValido,
      confianza: confianza,
      origen_message_id: origenMessageId,
      requiere_revision_humana: requiereRevision,
      revision_forzada: revisionForzada,
      ingreso_sellado_ausente: item.json.ingreso_sellado_ausente === true
    }
  });
}

return result;

// Marca el canal de origen como web antes de la normalizacion
const item = $input.item;
return [
  {
    json: {
      ...item.json,
      // C-39: instante de recepcion del webhook (borde del trigger web).
      ingresado_en: new Date().toISOString(),
      canal_raw: 'web'
    }
  }
];

// Registro de auditoria - C-05 (fix D-3/D-4 + B-14: shape real de backend, canal_origen upstream y resultado real)
// Contrato del evento: { incidente_id, canal_origen, timestamp, sector_nombre, confianza, resultado, retencion_dias }
// EXCLUSION DE PII: la descripcion cruda NO se incluye; solo metadatos y referencias.
// Retencion: 30 dias - declarada aqui; el destino persistente (Docker logging con rotacion)
// se configura en docker-compose.yml segun la guia operativa.
//
// Shape real del response 201 de POST /api/v1/incidentes:
//   { id, sector: { id, nombre, ... }, requiere_revision_humana, ... }
//   El campo 'sector.nombre' es la categoria asignada; no existe 'categoria' en la raiz.
//
// D-4: canal_origen y confianza se obtienen del nodo normalizador (aguas arriba),
//   NO del item corriente. Tras el HTTP POST el item corriente es el response body
//   del backend, que no incluye canal_origen ni confianza.
//   En la rama de rechazo el item ya viene con canal_origen del normalizador.
//
// Ramas que llegan a este nodo:
//   - Rama exitosa sin revision: response HTTP POST (id, sector.nombre, requiere_revision_humana)
//   - Rama exitosa con revision humana (C-57): response HTTP POST por el gate post-POST,
//     NO el resultado SMTP del envio de notificacion (que no trae id numerico)
//   - Rama de rechazo: item del normalizador (canal_origen, es_valido=false)
const item = $input.item.json;

// D-4: obtener canal_origen y confianza desde el nodo normalizador (fuente primaria).
// En la rama exitosa el item corriente (response HTTP) no incluye esos campos.
// En la rama de rechazo el item ya viene con canal_origen del normalizador.
let canalOrigen = null;
let confianza = null;
try {
  const normItem = $('Normalizar entrada del incidente').item.json;
  canalOrigen = normItem.canal_origen || null;
  confianza = normItem.confianza ?? null;
} catch (_) {
  // Si el nodo upstream no esta disponible, fallback al item corriente
  canalOrigen = item.canal_origen || item.canal_raw || null;
  confianza = item.confianza ?? null;
}

// D-3: leer sector.nombre del response HTTP (campo real del backend).
// El response 201 tiene: { id, sector: { nombre }, requiere_revision_humana, ... }
// En la rama de rechazo no hay response HTTP; sector es null.
const sectorNombre = item.sector?.nombre || null;

// B-14: distinguir creados de rechazados segun el resultado real del flujo.
// El normalizador emite un id sintetico (string) tambien en la rama de rechazo,
// por lo que 'item.id' NO alcanza para detectar un alta. El response del backend
// tiene id numerico; la rama de rechazo llega con es_valido = false.
const resultado = item.resultado
  || (item.error
      ? 'error_backend'
      : (item.es_valido === false
          ? 'rechazado_datos_incompletos'
          : (typeof item.id === 'number' ? 'creado' : 'rechazado_datos_incompletos')));

const evento = {
  incidente_id: item.id || null,
  canal_origen: canalOrigen,
  timestamp: new Date().toISOString(),
  sector_nombre: sectorNombre,
  confianza: confianza,
  resultado: resultado,
  retencion_dias: 30
};
console.log('[AUDITORIA]', JSON.stringify(evento));
return [{ json: evento }];

// C-33 (D7): destino no-op de la notificacion de clasificacion.
// El webhook dedicado NO crea incidentes: solo acusa recibo de la
// notificacion del backend para que el acoplamiento sea explicito.
const items = $input.all();
return items.map((item) => ({
  json: { evento: item.json.evento || 'notificacion', recibido: true }
}));
